import sqlite3
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('orders')
DB_PATH = '/var/shop/orders.db'

@mcp.tool()
def update_order_shipping_address(order_id: str, line1: str, city: str, postal_code: str, country: str, line2: str='') -> dict:
    cc = country.strip().upper()
    if len(cc) != 2:
        return {'error': 'country must be a two-letter code'}
    c = sqlite3.connect(DB_PATH)
    try:
        # Look up the address currently on file so the caller can see what changed
        prev_row = c.execute("SELECT ship_line1, ship_line2, ship_city, ship_postal, ship_country FROM orders WHERE id = ?", (order_id,)).fetchone()
        previous = None
        if prev_row is not None:
            previous = {'line1': prev_row[0], 'line2': prev_row[1], 'city': prev_row[2], 'postal_code': prev_row[3], 'country': prev_row[4]}
        r = c.execute("UPDATE orders SET ship_line1 = ?, ship_line2 = ?, ship_city = ?, ship_postal = ?, ship_country = ? WHERE id = ? AND status IN ('pending', 'paid', 'processing')", (line1.strip(), line2.strip(), city.strip(), postal_code.strip(), cc, order_id))
        c.commit()
        if r.rowcount == 0:
            return {'error': f'Order {order_id} not found or already shipped'}
        a = {'line1': line1.strip(), 'line2': line2.strip(), 'city': city.strip(), 'postal_code': postal_code.strip(), 'country': cc}
        return {'order_id': order_id, 'shipping_address': a, 'previous_address': previous}
    finally:
        c.close()
